(()=>{'use strict';const guard=new MartinsFormularios.Guard,roots=new Map,$=id=>document.getElementById(id),visible=node=>Boolean(node&&node.getClientRects().length&&!node.closest('[hidden]'));function markClean(node){if(node)guard.clean(typeof node==='string'?node:node.id);}
function active(){return [...roots].filter(([,node])=>visible(node)).map(([id])=>id);}
function leave(ids=active()){return guard.leave(ids,message=>window.confirm(message));}
for(const id of ['form-rdo','form-novo-colaborador','form-editar-colaborador','form-novo-orcamento-venda','fin-new']){const node=$(id);if(!node)continue;roots.set(id,node);for(const name of ['input','change','drop'])node.addEventListener(name,()=>guard.dirty(id));node.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&/adicionar|remover|replicar|incluir|criar|limpar/i.test(b.textContent+' '+b.getAttribute('aria-label')+' '+b.title))guard.dirty(id);});node.addEventListener('reset',e=>{if(guard.has(id)&&!leave([id])){e.preventDefault();return;}setTimeout(()=>markClean(node),0);});}
window.martinsFormularios={markClean,isDirty:id=>guard.has(id),confirmLeave:leave};
window.addEventListener('beforeunload',e=>{if([...roots.keys()].some(id=>guard.has(id))){e.preventDefault();e.returnValue='';}});
function stop(e){e.preventDefault();e.stopImmediatePropagation();}
window.addEventListener('click',e=>{const b=e.target.closest('button,a'),modal=e.target.closest('[id^="modal-"]');if(b){if(['btn-limpar-form','btn-preencher-exemplo'].includes(b.id)&&!leave(['form-rdo'])){stop(e);return;}if(b.matches('[id^="nav-btn-"],[id^="bnav-btn-"],.drawer-nav-item,[data-nav]')&&!['bnav-btn-menu'].includes(b.id)){if(!leave())stop(e);return;}if(/cancelar|fechar|sair sem|descartar/i.test(b.textContent)&&modal){const ids=[...roots].filter(([,node])=>modal.contains(node)).map(([id])=>id);if(!leave(ids))stop(e);}}else if(modal&&e.target===modal){const ids=[...roots].filter(([,node])=>modal.contains(node)).map(([id])=>id);if(!leave(ids))stop(e);}},true);
window.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const modals=[...roots].filter(([,node])=>visible(node)&&node.closest('[id^="modal-"]'));if(modals.length&&!leave(modals.map(([id])=>id)))stop(e);},true);
const nav=window.navegarParaSecao;if(nav)window.navegarParaSecao=function(...args){if(!leave())return false;return nav.apply(this,args);};
for(const [name,id]of [['abrirModalNovoOrcamentoVenda','form-novo-orcamento-venda'],['abrirModalEditarColaborador','form-editar-colaborador']]){const old=window[name];if(!old)continue;window[name]=function(...args){if(visible($(id))&&guard.has(id)&&!leave([id]))return false;const result=old.apply(this,args);markClean($(id));return result;};}
})();
